CommonData.PCCustomCSS:
/* Align the Preference Center logo to the left edge */
#onetrust-pc-sdk .ot-pc-logo img {
    margin-left: -26px !important; 
}
/* 1. Reset arrows and hidden elements (From your original CSS) */
#onetrust-pc-sdk .ot-arw-cntr .ot-arw {
    display: none !important;
}
.ot-btn-container > .ot-pc-refuse-all-handler { display: none !important; }
.ot-btn-container > .save-preference-btn-handler.onetrust-close-btn-handler { display: none !important; } 

/* 2. Convert parent to Flexbox and align everything to the left */
#onetrust-pc-sdk #ot-pc-content {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-start !important; /* Forces left alignment */
    height: 80%;
}

/* 3. Ensure accordions and text stay full width */
#onetrust-pc-sdk #ot-pc-content > * {
    width: 100%;
    order: 10; /* Pushes standard elements to the bottom by default */
}

/* 4. Lock text blocks to the top */
#onetrust-pc-sdk .ot-optout-signal { order: 1 !important; }
#onetrust-pc-sdk #ot-pc-title { order: 2 !important; }
#onetrust-pc-sdk #ot-pc-desc { order: 3 !important; }

/* 5. ACCEPT ALL: Force to Position 4 (Top Button) */
#onetrust-pc-sdk #accept-recommended-btn-handler {
    order: 4 !important;
    color: #fff !important;
    border-radius: 20px !important;
    width: 60% !important;
    max-width: 320px !important;
    height: auto !important;
    border: none !important;
    min-height: 52px !important;
    margin: 10px 0 10px 0 !important; /* Creates gap between buttons */
    padding: 12px 5px !important;
    float: none !important;
}

/* 6. ONLY NECESSARY: Force to Position 5 (Bottom Button) */
#onetrust-pc-sdk .ot-pc-refuse-all-handler {
    order: 5 !important;
    background-color: #4FA8D8 !important;
    color: #fff !important;
    width: 60% !important;
    max-width: 320px !important;
    border-radius: 20px !important;
    border: none !important;
    height: auto !important;
    min-height: 52px !important;
    margin: 0 0 25px 0 !important; /* Gap below to separate from accordions */
    padding: 12px 5px !important;
    /* No display rule here, so your JS toggle continues to work! */
}

/* 7. ACCEPT SELECTED (Save Preferences): Shares Position 5 */
#onetrust-pc-sdk .save-preference-btn-handler {
    order: 5 !important; /* Sits exactly where 'Only necessary' sits */
    background-color: #4FA8D8 !important;
    color: #fff !important;
    width: 60% !important;
    max-width: 320px !important;
    border-radius: 20px !important;
    border: none !important;
    height: auto !important;
    min-height: 52px !important;
    margin: 0 0 25px 0 !important; /* Matches gap above */
    padding: 12px 5px !important;
    display: none; /* Initially hidden, JS will change this to block */
}

/* 8. Drop Accordions to the bottom */
#onetrust-pc-sdk .ot-cat-grp { order: 6 !important; width: 100% !important; }
#onetrust-pc-sdk #ot-pc-lst { order: 7 !important; width: 100% !important; }

/* 9. Your remaining original styling rules */
#onetrust-pc-sdk .accordion-text.category-item {
    padding-top: 10px;
    padding-bottom: 5px;
    margin-top: 0;
}
#onetrust-pc-sdk .category-item {
    line-height: 1.1;
    margin-top: 10px;
    display: inline-block;
    width: 100%;
}
#onetrust-pc-sdk #cookie-preferences h4 {
    width: calc(100% - 42px);
    float: right;
}
#ot-sdk-btn.ot-sdk-show-settings, 
#ot-sdk-btn.optanon-show-settings {
    font-family: Verdana;
    font-size: 16px;
    color: #009fda;
    border: none;
}
#ot-sdk-btn.ot-sdk-show-settings:hover {
    color: #009fda;
    font-weight: bolder;
}
#onetrust-pc-sdk.otPcCenter {
    bottom: 10%;
}
#onetrust-pc-sdk .ot-pc-footer {
    z-index: 300;
}
@media only screen and (max-width: 600px) {
    #onetrust-pc-sdk #ot-pc-content { 
        height: 80%;
    }
}
/* Prevent Flexbox from squishing the text and buttons on smaller screens */
html body #onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-desc,
html body #onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-title,
html body #onetrust-consent-sdk #onetrust-pc-sdk #accept-recommended-btn-handler,
html body #onetrust-consent-sdk #onetrust-pc-sdk .ot-pc-refuse-all-handler,
html body #onetrust-consent-sdk #onetrust-pc-sdk .save-preference-btn-handler {
